// Attempt 1: the inheritance tower.
class Entity { describe() { return this.constructor.name; } }
class MovingEntity extends Entity { move() { return 'moves'; } }
class ShootingMover extends MovingEntity { shoot() { return 'shoots'; } }   // Guard
class HealingMover extends MovingEntity { heal() { return 'heals'; } }     // Medic

// Turret shoots but must NOT inherit move(). So it can't live under
// MovingEntity... which means shoot() gets written a second time:
class StaticEntity extends Entity {}
class ShootingStatic extends StaticEntity { shoot() { return 'shoots'; } } // Turret - DUPLICATED
class HealingStatic extends StaticEntity { heal() { return 'heals'; } }    // MediTurret - DUPLICATED

const guard = new ShootingMover();
const turret = new ShootingStatic();
console.log('Guard:', guard.move(), '+', guard.shoot());
console.log('Turret:', turret.shoot(), '- and no move(), as designed');
console.log();
console.log('Now design asks for a Medic that also shoots.');
console.log('Its parent must be... ShootingMover? HealingMover? Both?');
console.log('JS has no multiple inheritance - so we would duplicate heal()');
console.log('or shoot() a THIRD time. The tower loses. Single inheritance');
console.log('forces every capability combination to be a tree node, but');
console.log('capabilities combine like a GRID, not a tree.');
return 'inheritance: 2 duplicated methods for 4 species, and species #5 breaks it';

// Attempt 2: composition. Components are plain data.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(20260710);
const pick = () => ({ x: 60 + rand() * 800, y: 60 + rand() * 400 });
const vel = () => ({ dx: (rand() - 0.5) * 3, dy: (rand() - 0.5) * 3 });

let nextId = 1;
const make = (species, components) => ({ id: nextId++, species, ...components });

const world = [
  make('guard',      { pos: pick(), vel: vel(), shooter: { range: 150 }, hp: 100 }),
  make('guard',      { pos: pick(), vel: vel(), shooter: { range: 150 }, hp: 100 }),
  make('turret',     { pos: pick(), shooter: { range: 220 }, hp: 80 }),
  make('medic',      { pos: pick(), vel: vel(), healer: { rate: 2, range: 130 }, hp: 60 }),
  make('mediturret', { pos: pick(), healer: { rate: 3, range: 180 }, hp: 90 }),
  // the species that broke the tower - just a different bag:
  make('warmedic',   { pos: pick(), vel: vel(), shooter: { range: 120 }, healer: { rate: 1, range: 100 }, hp: 80 }),
];

// Systems: behaviour = a function over entities WITH a component.
const systems = {
  move:  w => w.filter(e => e.vel).length + ' entities move',
  shoot: w => w.filter(e => e.shooter).length + ' entities shoot',
  heal:  w => w.filter(e => e.healer).length + ' entities heal',
};
for (const [name, run] of Object.entries(systems)) console.log(name + ':', run(world));

console.log();
console.log('capability grid (no duplication anywhere):');
for (const e of world) {
  console.log('  ' + e.species.padEnd(11) +
    (e.vel ? ' [moves]' : '        ') +
    (e.shooter ? ' [shoots]' : '         ') +
    (e.healer ? ' [heals]' : ''));
}

nb.set('ecs_world', world);
return 'published as ecs_world - the arena below brings the systems to life';
